// Outbox: business row and event row commit together, or neither does
var payment = Payment.Create(cmd.OrderId, cmd.Amount);
db.Payments.Add(payment);
db.OutboxMessages.Add(new OutboxMessage
{
    Id = Guid.NewGuid(),                 // consumers dedupe on this id
    Type = "PaymentRequested",
    Payload = JsonSerializer.Serialize(new { payment.Id, cmd.OrderId, cmd.Amount }),
    OccurredAt = DateTime.UtcNow
});
await db.SaveChangesAsync(ct);           // one local SQL transaction

// OutboxRelay : BackgroundService, every few seconds:
//   read unprocessed rows ordered by OccurredAt
//   produce each to Kafka (key = OrderId), await the delivery report
//   mark ProcessedAt; a crash before this line means a resend, never a loss

var config = new ConsumerConfig
{
    BootstrapServers = "broker:9092",
    GroupId = "payroll-service",
    AutoOffsetReset = AutoOffsetReset.Earliest,
    EnableAutoCommit = true,            // background commit of stored offsets...
    EnableAutoOffsetStore = false,      // ...but we store only after handling
    PartitionAssignmentStrategy = PartitionAssignmentStrategy.CooperativeSticky
};
using var consumer = new ConsumerBuilder<string, string>(config).Build();
consumer.Subscribe("employee-events");
while (!ct.IsCancellationRequested)
{
    var cr = consumer.Consume(ct);
    try { await handler.HandleAsync(cr.Message, ct); }   // idempotent on event id
    catch (Exception ex) { await SendToDeadLetterAsync(cr, ex, ct); }
    consumer.StoreOffset(cr);           // at-least-once: mark done after handling
}

var producerConfig = new ProducerConfig
{
    BootstrapServers = "broker:9092",
    EnableIdempotence = true,           // implies Acks.All, no duplicate retries
};

builder.Services.AddProblemDetails();     // RFC 9457 error bodies
builder.Services.AddOpenApi();            // built in since .NET 9
var app = builder.Build();
app.MapOpenApi();                         // serves /openapi/v1.json

app.MapPost("/v1/payments", async (CreatePayment cmd,
    [FromHeader(Name = "Idempotency-Key")] Guid key, PaymentsDb db) =>
{
    var seen = await db.IdempotencyKeys.FindAsync(key);
    if (seen is not null)
        return seen.RequestHash == cmd.Hash()
            ? Results.Json(seen.Body, statusCode: seen.Status)   // replay, no 2nd charge
            : Results.Problem(statusCode: 422,
                title: "Idempotency-Key reused with a different request");

    var payment = await payments.ChargeAsync(cmd);
    db.IdempotencyKeys.Add(new(key, cmd.Hash(), 201, payment)); // unique index on key
    await db.SaveChangesAsync();
    return Results.Created($"/v1/payments/{payment.Id}", payment);
});

builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(o =>
    {
        o.Authority = "https://login.example.com/";   // discovery + JWKS from here
        o.Audience = "payroll-api";                   // reject tokens for other APIs
        o.TokenValidationParameters = new()
        {
            ValidateIssuer = true,
            ValidateAudience = true,
            ValidateLifetime = true,
            ClockSkew = TimeSpan.FromMinutes(1),       // default is 5 minutes
            RoleClaimType = "roles"
        };
    });

builder.Services.AddAuthorization(o =>
    o.AddPolicy("PayrollApprover", p => p
        .RequireRole("payroll-admin")
        .RequireClaim("dept", "finance")));

app.MapPost("/payroll-runs/{id}/approval", Approve)
   .RequireAuthorization("PayrollApprover");
